package com.myproject.video.video_platform.controller.commerce;

import com.fasterxml.jackson.databind.*;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.entitlement.*;
import com.myproject.video.video_platform.entity.products.*;
import com.myproject.video.video_platform.entity.products.course.*;
import com.myproject.video.video_platform.entity.products.download.*;
import com.myproject.video.video_platform.entity.products.consultation.*;
import com.myproject.video.video_platform.entity.products.membership.*;
import com.myproject.video.video_platform.entity.entitlement.*;
import com.myproject.video.video_platform.entity.user.*;
import com.myproject.video.video_platform.repository.auth.*;
import com.myproject.video.video_platform.repository.products.*;
import com.myproject.video.video_platform.repository.products.course.*;
import com.myproject.video.video_platform.repository.products.download.*;
import com.myproject.video.video_platform.repository.products.consultation.*;
import com.myproject.video.video_platform.repository.commerce.*;
import com.myproject.video.video_platform.repository.entitlement.*;
import com.myproject.video.video_platform.service.security.*;
import com.myproject.video.video_platform.service.mail.*;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.presigner.S3Presigner;
import java.util.*;
import java.util.concurrent.*;
import java.math.BigDecimal;
import java.time.Instant;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest(properties={"app.commerce.fake.auto-success=false"})
class CatalogCheckoutMatrixTest extends CommerceCheckoutIntegrationTest {
  static final Queue<Map<String,Object>> observations=new ConcurrentLinkedQueue<>();
  @Autowired MockMvc mvc;
  @Autowired ObjectMapper mapper;
  @Autowired UserRepository users;
  @Autowired ProductRepository products;
  @Autowired DownloadProductRepository downloads;
  @Autowired ConsultationProductRepository consultations;
  @Autowired CourseSectionRepository sections;
  @Autowired CourseLessonRepository lessons;
  @Autowired ProductEntitlementRepository grants;
  @Autowired CommerceOrderRepository orders;
  @Autowired org.springframework.jdbc.core.JdbcTemplate jdbc;
  @Autowired CommercePaymentAttemptRepository attempts;
  @Autowired CommercePaymentEventRepository events;
  @Autowired JwtProvider jwt;
  @MockBean EmailService mail;
  @MockBean GoogleTokenVerifier google;
  @MockBean S3Client s3;
  @MockBean S3Presigner presigner;
  User buyer,owner,admin;
  @BeforeEach void catalogFixtures(){
    buyer=users.findByEmail("buyer@example.com").orElseThrow();owner=users.findByEmail("creator@example.com").orElseThrow();admin=users.findByEmail("admin@example.com").orElseThrow();
  }
  @AfterEach void catalogCleanup(){downloads.deleteAll();consultations.deleteAll();verifyNoInteractions(mail,google,s3,presigner);}
  Cookie auth(User u){return new Cookie("JWT_TOKEN",jwt.generateToken(u));}
  User extra(String name,User template){User u=new User();u.setUserId(UUID.randomUUID());u.setEmail(name+"@example.invalid");u.setPassword("synthetic-unused-password");u.setFirstName("QA");u.setLastName(name);u.setEnabled(true);u.setRoles(Set.copyOf(template.getRoles()));return users.saveAndFlush(u);}
  Product seed(ProductType type,User creator,String price,ProductStatus state){
    Product p=switch(type){case COURSE->new CourseProduct();case DOWNLOAD->new DownloadProduct();case CONSULTATION->new ConsultationProduct();case MEMBERSHIP->new MembershipProduct();};
    p.setName("QA "+type+" "+UUID.randomUUID());p.setDescription("Synthetic isolated catalog fixture");p.setUser(creator);p.setType(type);p.setStatus(state);p.setPrice(price==null?null:new BigDecimal(price));p.setPricingModel(type==ProductType.MEMBERSHIP?ProductPricingModel.RECURRING:ProductPricingModel.ONE_TIME);p.setCurrency(ProductCurrency.EUR);if(type==ProductType.MEMBERSHIP)p.setBillingInterval(ProductBillingInterval.MONTH);return products.saveAndFlush(p);
  }
  Product paid(){return seed(ProductType.COURSE,owner,"12.25",ProductStatus.PUBLISHED);}
  MockHttpServletRequestBuilder mutation(MockHttpServletRequestBuilder b,User u){return b.cookie(auth(u),new Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf").contentType(MediaType.APPLICATION_JSON);}
  JsonNode perform(String caseId,String label,MockHttpServletRequestBuilder req,int expected) throws Exception {
    MvcResult result=mvc.perform(req).andReturn();int status=result.getResponse().getStatus();String text=result.getResponse().getContentAsString();JsonNode body=text.isEmpty()?mapper.nullNode():mapper.readTree(text);
    Map<String,Object> row=new LinkedHashMap<>();row.put("case_id",caseId);row.put("label",label);row.put("method",req.buildRequest(new org.springframework.mock.web.MockServletContext()).getMethod());row.put("actual_status",status);row.put("expected_status",expected);row.put("orders",orders.count());row.put("attempts",attempts.count());row.put("events",events.count());row.put("entitlements",grants.count());row.put("observed_at",Instant.now().toString());observations.add(row);
    assertEquals(expected,status,caseId+" "+label+" HTTP status");return body;
  }
  JsonNode checkout(String c,String label,User who,List<UUID> ids,String key,int status) throws Exception {MockHttpServletRequestBuilder req=mutation(post("/api/commerce/checkout-sessions"),who).content(mapper.writeValueAsString(Map.of("productIds",ids)));if(key!=null)req.header("Idempotency-Key",key);return perform(c,label,req,status);}
  void noFinancialRecords(){assertEquals(0,orders.count());assertEquals(0,attempts.count());assertEquals(0,events.count());assertEquals(0,grants.count());}
  void readyArticle(Product p){CourseSection section=new CourseSection();section.setCourse((CourseProduct)p);section.setTitle("QA Section");section.setDescription("QA");section.setPosition(1);section=sections.saveAndFlush(section);CourseLesson lesson=new CourseLesson();lesson.setSection(section);lesson.setTitle("QA Article");lesson.setDescription("QA");lesson.setPosition(1);lesson.setType(com.myproject.video.video_platform.common.enums.products.course.LessonType.ARTICLE);lesson.setContent("QA ready article");lessons.saveAndFlush(lesson);}

  @Test void pay002PendingOneAndTwentyAcrossTypes() throws Exception {
    int expectedOrders=0;
    for(ProductType type:List.of(ProductType.COURSE,ProductType.DOWNLOAD,ProductType.CONSULTATION))for(int count:List.of(1,20)){
      List<UUID> ids=new ArrayList<>();for(int i=0;i<count;i++)ids.add(seed(type,owner,"2.25",ProductStatus.PUBLISHED).getId());
      JsonNode order=checkout("PAY-002",type+"-count-"+count,buyer,ids,"size-"+type+count,201);expectedOrders++;
      assertEquals("PENDING",order.path("status").asText());assertEquals("EUR",order.path("currency").asText());assertEquals("FAKE",order.path("provider").asText());assertEquals(count,order.path("items").size());assertEquals(225L*count,order.path("totalMinor").asLong());assertTrue(order.path("checkoutUrl").isNull()||order.path("checkoutUrl").isMissingNode());assertTrue(Instant.parse(order.path("expiresAt").asText()).isAfter(Instant.now()));
      Set<UUID> returnedIds=new HashSet<>();Set<String> itemIds=new HashSet<>();assertEquals(225L*count,order.path("subtotalMinor").asLong());for(JsonNode item:order.path("items")){UUID productId=UUID.fromString(item.path("productId").asText());returnedIds.add(productId);itemIds.add(item.path("id").asText());assertEquals(type.name(),item.path("productType").asText());assertEquals(products.findById(productId).orElseThrow().getName(),item.path("productName").asText());assertEquals(1,item.path("quantity").asInt());assertEquals(225,item.path("unitAmountMinor").asLong());assertEquals(225,item.path("lineTotalMinor").asLong());}assertEquals(new HashSet<>(ids),returnedIds);assertEquals(count,itemIds.size());
      UUID id=UUID.fromString(order.path("orderId").asText());assertEquals("PENDING",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertEquals(expectedOrders,orders.count());assertEquals(expectedOrders,attempts.count());assertEquals(0,grants.count());assertEquals(0,events.count());
      JsonNode read=perform("PAY-002",type+"-count-"+count+"-read",get("/api/commerce/orders/"+id).cookie(auth(buyer)),200);assertEquals(order,read);
    }
  }
  @Test void pay003DtoBoundaries() throws Exception {
    List<String> bodies=new ArrayList<>(List.of("{}","{\"productIds\":null}","{\"productIds\":[]}","{\"productIds\":[null]}","{\"productIds\":[\"not-a-uuid\"]}"));List<UUID> ids=new ArrayList<>();for(int i=0;i<21;i++)ids.add(UUID.randomUUID());bodies.add(mapper.writeValueAsString(Map.of("productIds",ids)));
    for(int i=0;i<bodies.size();i++){perform("PAY-003","invalid-body-"+i,mutation(post("/api/commerce/checkout-sessions"),buyer).header("Idempotency-Key","dto-"+i).content(bodies.get(i)),400);noFinancialRecords();}
  }
  @Test void pay004IdempotencyHeaderBoundaries() throws Exception {
    UUID p=paid().getId();for(String key:Arrays.asList(null,"","   ","x".repeat(129))){checkout("PAY-004","rejected-key-"+(key==null?"missing":key.length()),buyer,List.of(p),key,400);noFinancialRecords();}
    checkout("PAY-004","length128",buyer,List.of(p),"x".repeat(128),201);JsonNode trim=checkout("PAY-004","whitespace-trim",buyer,List.of(p),"  qa-trimmed  ",201);JsonNode repeat=checkout("PAY-004","trimmed-replay",buyer,List.of(p),"qa-trimmed",201);assertEquals(trim.path("orderId"),repeat.path("orderId"));assertEquals(2,orders.count());assertEquals(0,grants.count());
  }
  @Test void pay005StableReplayAcrossEdits() throws Exception {
    Product a=paid(),b=paid();readyArticle(a);readyArticle(b);JsonNode original=checkout("PAY-005","original",buyer,List.of(a.getId(),b.getId()),"stable",201);
    assertEquals(original,checkout("PAY-005","reordered",buyer,List.of(b.getId(),a.getId()),"stable",201));
    for(String patch:List.of("{\"name\":\"QA Updated title\"}","{\"price\":\"27.50\"}","{\"status\":\"HIDDEN\"}")){
      perform("PAY-005","supported-product-patch",mutation(patch("/api/products/"+a.getId()),owner).content(patch),200);
      assertEquals(original,checkout("PAY-005","replay-after-patch-"+patch,buyer,List.of(a.getId(),b.getId()),"stable",201));
    }
    Product changed=products.findById(a.getId()).orElseThrow();assertEquals("QA Updated title",changed.getName());assertEquals(0,changed.getPrice().compareTo(new BigDecimal("27.50")));assertEquals(ProductStatus.HIDDEN,changed.getStatus());assertEquals(1,orders.count());assertEquals(1,attempts.count());assertEquals(0,grants.count());
  }
  @Test void pay006ConflictingPayloadAndBuyerScope() throws Exception {
    Product a=paid(),b=paid();JsonNode first=checkout("PAY-006","original-A",buyer,List.of(a.getId()),"scope",201);
    checkout("PAY-006","changed-B",buyer,List.of(b.getId()),"scope",409);checkout("PAY-006","changed-A-plus-B",buyer,List.of(a.getId(),b.getId()),"scope",409);assertEquals(1,orders.count());
    User other=extra("other-buyer",buyer);JsonNode independent=checkout("PAY-006","independent-buyer-key",other,List.of(a.getId()),"scope",201);assertNotEquals(first.path("orderId"),independent.path("orderId"));assertEquals(2,orders.count());assertEquals(2,attempts.count());assertEquals(0,grants.count());
  }
  @Test void pay007ConcurrentIdenticalCheckout() throws Exception {
    Product p=paid();ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);
    try{List<Future<JsonNode>> calls=new ArrayList<>();for(int i=0;i<2;i++){int n=i;calls.add(pool.submit(()->{start.await();return checkout("PAY-007","concurrent-"+n,buyer,List.of(p.getId()),"concurrent",201);}));}start.countDown();JsonNode a=calls.get(0).get(20,TimeUnit.SECONDS),b=calls.get(1).get(20,TimeUnit.SECONDS);assertEquals(a.path("orderId"),b.path("orderId"));assertEquals(1,orders.count());assertEquals(1,attempts.count());assertEquals(1L,jdbc.queryForObject("SELECT COUNT(*) FROM commerce_order_items",Long.class));assertEquals(1,a.path("items").size());assertEquals(1,b.path("items").size());assertEquals(0,grants.count());assertEquals(0,events.count());}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}
  }
  @Test void pay008DuplicateAndMissing() throws Exception {Product p=paid();checkout("PAY-008","duplicate",buyer,List.of(p.getId(),p.getId()),"duplicate",422);noFinancialRecords();checkout("PAY-008","missing-only",buyer,List.of(UUID.randomUUID()),"missing",422);noFinancialRecords();checkout("PAY-008","valid-plus-missing",buyer,List.of(p.getId(),UUID.randomUUID()),"partial-missing",422);noFinancialRecords();}
  @Test void pay009FreeAndUnpublished() throws Exception {Product valid=paid();List<Product> invalid=List.of(seed(ProductType.COURSE,owner,"0",ProductStatus.PUBLISHED),seed(ProductType.COURSE,owner,null,ProductStatus.PUBLISHED),seed(ProductType.COURSE,owner,"5",ProductStatus.DRAFT),seed(ProductType.COURSE,owner,"5",ProductStatus.HIDDEN));int i=0;for(Product p:invalid){checkout("PAY-009","valid-plus-invalid-"+i,buyer,List.of(valid.getId(),p.getId()),"state-"+i++,422);noFinancialRecords();}}
  @Test void pay010MembershipAndRecurring() throws Exception {Product membership=seed(ProductType.MEMBERSHIP,owner,"12",ProductStatus.PUBLISHED);checkout("PAY-010","legacy-published-membership",buyer,List.of(membership.getId()),"membership",422);noFinancialRecords();Product recurring=paid();recurring.setPricingModel(ProductPricingModel.RECURRING);recurring.setBillingInterval(ProductBillingInterval.MONTH);products.saveAndFlush(recurring);checkout("PAY-010","recurring-course",buyer,List.of(recurring.getId()),"recurring",422);noFinancialRecords();}
  @Test void pay011OwnerAndAdminSelfPurchase() throws Exception {for(User u:List.of(owner,admin)){Product own=seed(ProductType.COURSE,u,"5",ProductStatus.PUBLISHED);checkout("PAY-011","self-"+u.getRoles().iterator().next().getRoleName(),u,List.of(own.getId()),"self-"+u.getUserId(),422);noFinancialRecords();}}
  @Test void pay012MixedCreators() throws Exception {Product a=paid();User other=extra("other-creator",owner);Product b=seed(ProductType.COURSE,other,"8",ProductStatus.PUBLISHED);checkout("PAY-012","two-creators",buyer,List.of(a.getId(),b.getId()),"mixed",422);noFinancialRecords();}
  @Test void pay015ReadRoleMatrixAndMissing() throws Exception {Product p=paid();JsonNode order=checkout("PAY-015","create-pending",buyer,List.of(p.getId()),"read-order",201);String url="/api/commerce/orders/"+order.path("orderId").asText();assertEquals(order,perform("PAY-015","buyer",get(url).cookie(auth(buyer)),200));assertEquals(order,perform("PAY-015","admin",get(url).cookie(auth(admin)),200));perform("PAY-015","seller",get(url).cookie(auth(owner)),403);perform("PAY-015","unrelated-user",get(url).cookie(auth(extra("unrelated",buyer))),403);perform("PAY-015","unknown-order",get("/api/commerce/orders/"+UUID.randomUUID()).cookie(auth(buyer)),404);perform("PAY-015","guest",get(url),401);assertEquals(1,orders.count());assertEquals(0,grants.count());}
  @Test void access001FreeEnrollmentAllRolesTypesAndPrices() throws Exception {
    User second=extra("enrollment-product-owner",owner);int total=0;
    for(User u:List.of(buyer,owner,admin))for(ProductType type:List.of(ProductType.COURSE,ProductType.DOWNLOAD,ProductType.CONSULTATION))for(String price:Arrays.asList(null,"0")){
      Product p=seed(type,second,price,ProductStatus.PUBLISHED);String label=u.getRoles().iterator().next().getRoleName()+"-"+type+"-"+(price==null?"null":"zero");JsonNode created=perform("ACCESS-001",label+"-enroll",mutation(post("/api/entitlements/products/"+p.getId()+"/enroll"),u),201);assertEquals("FREE_ENROLLMENT",created.path("source").asText());assertEquals(p.getId().toString(),created.path("product").path("id").asText());total++;
      ProductEntitlement persisted=grants.findByUserUserIdAndProductId(u.getUserId(),p.getId()).orElseThrow();assertEquals(EntitlementStatus.ACTIVE,persisted.getStatus());assertEquals(EntitlementSource.FREE_ENROLLMENT,persisted.getSource());assertNull(persisted.getPurchaseOrderItemId());assertNull(persisted.getRevokedAt());assertEquals(total,grants.count());
      JsonNode library=perform("ACCESS-001",label+"-library",get("/api/entitlements/me").cookie(auth(u)),200);assertTrue(java.util.stream.StreamSupport.stream(library.spliterator(),false).anyMatch(x->x.path("product").path("id").asText().equals(p.getId().toString())));
      assertTrue(perform("ACCESS-001",label+"-access",get("/api/entitlements/products/"+p.getId()+"/access").cookie(auth(u)),200).path("hasAccess").asBoolean());
    }
    assertEquals(0,orders.count());assertEquals(0,events.count());
  }
  @Test void access003PaidLifecycleAndMissingAllRoles() throws Exception {List<Product> invalid=List.of(seed(ProductType.COURSE,owner,"5",ProductStatus.PUBLISHED),seed(ProductType.COURSE,owner,"0",ProductStatus.DRAFT),seed(ProductType.COURSE,owner,"0",ProductStatus.HIDDEN));for(User u:List.of(buyer,owner,admin)){int i=0;for(Product p:invalid){perform("ACCESS-003",u.getRoles().iterator().next().getRoleName()+"-"+p.getStatus(),mutation(post("/api/entitlements/products/"+p.getId()+"/enroll"),u),i++==0?402:403);assertEquals(0,grants.count());}perform("ACCESS-003","missing-"+u.getRoles().iterator().next().getRoleName(),mutation(post("/api/entitlements/products/"+UUID.randomUUID()+"/enroll"),u),404);assertEquals(0,grants.count());}assertEquals(0,orders.count());}
  @Test void access006BooleanMatrix() throws Exception {Product p=paid();String url="/api/entitlements/products/"+p.getId()+"/access";assertTrue(perform("ACCESS-006","owner",get(url).cookie(auth(owner)),200).path("hasAccess").asBoolean());assertTrue(perform("ACCESS-006","admin",get(url).cookie(auth(admin)),200).path("hasAccess").asBoolean());assertEquals(0,grants.count());ProductEntitlement grant=new ProductEntitlement();grant.setUser(buyer);grant.setProductId(p.getId());grant.setProductType(p.getType());grant.setStatus(EntitlementStatus.ACTIVE);grant.setSource(EntitlementSource.ADMIN_GRANT);grant=grants.saveAndFlush(grant);assertTrue(perform("ACCESS-006","active-holder",get(url).cookie(auth(buyer)),200).path("hasAccess").asBoolean());grant.setStatus(EntitlementStatus.REVOKED);grant.setRevokedAt(Instant.now());grants.saveAndFlush(grant);assertFalse(perform("ACCESS-006","revoked-holder",get(url).cookie(auth(buyer)),200).path("hasAccess").asBoolean());assertFalse(perform("ACCESS-006","unrelated",get(url).cookie(auth(extra("access-unrelated",buyer))),200).path("hasAccess").asBoolean());perform("ACCESS-006","guest",get(url),401);assertEquals(1,grants.count());}
}

package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.JsonNode;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.entitlement.*;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.entitlement.ProductEntitlement;
import com.myproject.video.video_platform.entity.user.User;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
class CatalogPaymentStateTest extends CatalogCheckoutMatrixTest {
 UUID orderId(JsonNode n){return UUID.fromString(n.path("orderId").asText());}
 JsonNode simulate(String c,UUID id,String outcome,int status)throws Exception{return perform(c,"simulate-"+outcome,mutation(post("/api/dev/commerce/orders/"+id+"/simulate"),admin).content(mapper.writeValueAsString(Map.of("outcome",outcome))),status);}
 JsonNode readOrder(String c,UUID id)throws Exception{return perform(c,"buyer-order-read",get("/api/commerce/orders/"+id).cookie(auth(buyer)),200);}
 JsonNode library(String c)throws Exception{return perform(c,"buyer-library",get("/api/entitlements/me").cookie(auth(buyer)),200);}
 Set<UUID> libraryIds(String c)throws Exception{Set<UUID> ids=new HashSet<>();for(JsonNode n:library(c))ids.add(UUID.fromString(n.path("product").path("id").asText()));return ids;}
 ProductEntitlement grant(Product p,User u,EntitlementSource source,EntitlementStatus status){ProductEntitlement e=new ProductEntitlement();e.setUser(u);e.setProductId(p.getId());e.setProductType(p.getType());e.setSource(source);e.setStatus(status);if(status==EntitlementStatus.REVOKED)e.setRevokedAt(Instant.now());return grants.saveAndFlush(e);}
 void access(String c,Product p,boolean expected)throws Exception{assertEquals(expected,perform(c,"access-"+expected,get("/api/entitlements/products/"+p.getId()+"/access").cookie(auth(buyer)),200).path("hasAccess").asBoolean());}
 void content(String c,Product p,boolean expected)throws Exception{JsonNode n=perform(c,"protected-course-content-"+expected,get("/api/products/"+p.getId()).cookie(auth(buyer)),200);assertEquals(expected,n.toString().contains("QA ready article"));}
 String metric(String c,String label)throws Exception{JsonNode n=perform(c,"creator-summary-"+label,get("/api/creator/sales/summary").cookie(auth(owner)),200);for(JsonNode m:n.path("metrics"))if(m.path("label").asText().equals(label))return m.path("value").asText();throw new AssertionError("Expected summary label absent: "+label);}
 JsonNode creatorOrder(String c,UUID id,String state)throws Exception{JsonNode n=perform(c,"creator-order-"+state,get("/api/creator/orders/"+id).cookie(auth(owner)),200);assertEquals(state.toLowerCase(Locale.ROOT),n.path("status").asText());JsonNode page=perform(c,"creator-ledger-"+state,get("/api/creator/orders").param("status",state.toLowerCase(Locale.ROOT)).cookie(auth(owner)),200);assertTrue(java.util.stream.StreamSupport.stream(page.path("content").spliterator(),false).anyMatch(x->x.path("id").asText().equals(id.toString())));return n;}
 void overdue(UUID id){var o=orders.findById(id).orElseThrow();o.setExpiresAt(Instant.now().minusSeconds(120));orders.saveAndFlush(o);}
 @Test void pay013AlreadyEntitledCartAtomicRejection()throws Exception{Product a=paid(),b=paid();grant(a,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);checkout("PAY-013","entitled-plus-unowned",buyer,List.of(a.getId(),b.getId()),"already",409);assertEquals(0,orders.count());assertEquals(0,attempts.count());assertEquals(0,events.count());assertEquals(1,grants.count());assertTrue(grants.findByUserUserIdAndProductId(buyer.getUserId(),b.getId()).isEmpty());}
 @Test void pay016PaidEveryItemAndProtectedAccess()throws Exception{List<Product> ps=List.of(paid(),seed(ProductType.DOWNLOAD,owner,"4.00",ProductStatus.PUBLISHED),seed(ProductType.CONSULTATION,owner,"8.00",ProductStatus.PUBLISHED));readyArticle(ps.get(0));JsonNode pending=checkout("PAY-016","pending-three-types",buyer,ps.stream().map(Product::getId).toList(),"paid",201);UUID id=orderId(pending);assertEquals("PENDING",pending.path("status").asText());assertEquals(0,grants.count());JsonNode paid=simulate("PAY-016",id,"PAID",200);assertEquals("PAID",paid.path("status").asText());assertEquals(paid,readOrder("PAY-016",id));assertEquals("SUCCEEDED",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertNotNull(orders.findById(id).orElseThrow().getPaidAt());assertEquals(3,grants.count());for(JsonNode item:paid.path("items")){UUID pid=UUID.fromString(item.path("productId").asText());ProductEntitlement e=grants.findByUserUserIdAndProductId(buyer.getUserId(),pid).orElseThrow();assertEquals(EntitlementStatus.ACTIVE,e.getStatus());assertEquals(EntitlementSource.PURCHASE,e.getSource());assertEquals(UUID.fromString(item.path("id").asText()),e.getPurchaseOrderItemId());assertNull(e.getRevokedAt());}assertEquals(new HashSet<>(ps.stream().map(Product::getId).toList()),libraryIds("PAY-016"));for(Product p:ps)access("PAY-016",p,true);content("PAY-016",ps.get(0),true);assertEquals(pending.path("items"),paid.path("items"));assertEquals(1,events.count());}
 @Test void pay017FailedNoGrantAndCreatorReports()throws Exception{Product p=paid();UUID id=orderId(checkout("PAY-017","pending",buyer,List.of(p.getId()),"failed",201));assertEquals("FAILED",simulate("PAY-017",id,"FAILED",200).path("status").asText());assertEquals("FAILED",readOrder("PAY-017",id).path("status").asText());assertEquals("FAILED",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertNotNull(orders.findById(id).orElseThrow().getFailedAt());assertEquals(0,grants.count());assertEquals(0,library("PAY-017").size());access("PAY-017",p,false);JsonNode detail=creatorOrder("PAY-017",id,"FAILED");assertFalse(detail.path("failure").isNull());assertEquals("1",metric("PAY-017","Failed payments"));assertEquals("0",metric("PAY-017","Orders"));}
